// This is a COMPLETE Spring Boot application — seriously, this is it.
@SpringBootApplication  // combines @Configuration + @EnableAutoConfiguration + @ComponentScan
public class MyApp {
    public static void main(String[] args) {
        SpringApplication.run(MyApp.class, args);  // starts embedded Tomcat
    }
}

// A working REST endpoint — add this file and you have an API
@RestController
@RequestMapping("/api/greetings")
public class GreetingController {

    @GetMapping("/{name}")
    public Map<String, String> greet(@PathVariable String name) {
        return Map.of(
            "message", "Hello, " + name + "!",
            "timestamp", Instant.now().toString()
        );
    }
}

// That's it. Run the main method → http://localhost:8080/api/greetings/Alice works.
// No web.xml, no applicationContext.xml, no server installation.

// SPRING BOOT vs SPRING — configuration comparison

// SPRING (traditional) — XML configuration for a simple web app:
// web.xml (servlet mapping), applicationContext.xml (bean definitions),
// dispatcher-servlet.xml (MVC config), pom.xml (15+ individual dependencies)
// Total: 4 XML files + 50-100 lines of config before writing any business logic

// SPRING BOOT — same web app:
// pom.xml with ONE starter, ONE annotated class, ZERO XML files
// That's it. Start coding immediately.

// application.properties — the single config file
// server.port=8080
// spring.datasource.url=jdbc:postgresql://localhost:5432/mydb
// spring.datasource.username=admin
// spring.jpa.hibernate.ddl-auto=validate
// logging.level.org.springframework=INFO

// SPRING BOOT DEVTOOLS — faster development
// Add to pom.xml: spring-boot-devtools
// What it gives you:
// 1. Auto-restart: change code → app restarts automatically (~2 seconds)
// 2. LiveReload: browser refreshes automatically
// 3. Relaxed caching: templates are not cached in dev mode

// SPRING BOOT ACTUATOR — production monitoring
@SpringBootApplication
public class MyApp {
    public static void main(String[] args) {
        SpringApplication.run(MyApp.class, args);
    }
}
// Add spring-boot-starter-actuator to pom.xml
// GET /actuator/health  → {"status": "UP"}
// GET /actuator/metrics  → JVM memory, HTTP request counts, DB pool stats
// GET /actuator/info     → build info, git commit, custom metadata

// 1. Define an interface (the contract)
public interface UserRepository {
    User findById(Long id);
    void save(User user);
}

// 2. Implement it — Spring manages this as a bean
@Repository
public class JpaUserRepository implements UserRepository {
    @Override
    public User findById(Long id) { /* JPA logic */ }
    @Override
    public void save(User user) { /* JPA logic */ }
}

// 3. Service receives the dependency via constructor injection (preferred)
@Service
public class UserService {
    private final UserRepository userRepository;  // interface type

    // Spring sees this constructor, finds a UserRepository bean,
    // and injects JpaUserRepository automatically.
    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public User getUser(Long id) {
        return userRepository.findById(id);
    }
}

// 4. In tests — inject a mock, no database needed
@Test
void getUser_returnsUser() {
    UserRepository mockRepo = mock(UserRepository.class);
    when(mockRepo.findById(1L)).thenReturn(new User(1L, "Alice"));

    UserService service = new UserService(mockRepo);  // inject mock
    User result = service.getUser(1L);

    assertEquals("Alice", result.getName());
}

// THREE TYPES OF INJECTION — and why constructor wins

// 1. CONSTRUCTOR INJECTION (preferred)
@Service
public class OrderService {
    private final PaymentGateway paymentGateway;  // final = immutable
    private final InventoryService inventoryService;

    // Spring 4.3+: single constructor = auto-injected, no @Autowired needed
    public OrderService(PaymentGateway payment, InventoryService inventory) {
        this.paymentGateway = payment;
        this.inventoryService = inventory;
    }
}

// 2. SETTER INJECTION (for optional dependencies)
@Service
public class NotificationService {
    private EmailSender emailSender;

    @Autowired(required = false)  // optional — app works without it
    public void setEmailSender(EmailSender emailSender) {
        this.emailSender = emailSender;
    }
}

// 3. FIELD INJECTION (avoid in production — hard to test)
@Service
public class BadService {
    @Autowired  // don't do this — can't set in tests without Spring
    private UserRepository repo;
}

// QUALIFIER — resolving ambiguity
public interface NotificationChannel {
    void send(String message);
}

@Component("email")
public class EmailChannel implements NotificationChannel { ... }

@Component("sms")
public class SmsChannel implements NotificationChannel { ... }

@Service
public class AlertService {
    public AlertService(@Qualifier("email") NotificationChannel channel) {
        // Spring injects EmailChannel, not SmsChannel
    }
}
